# ============================================================
# UTILITIES
# ============================================================
def get_pdf_hash(pdf_path: str) -> str:
    h = hashlib.md5()
    with open(pdf_path, "rb") as f:
        h.update(f.read())
    return h.hexdigest()

def format_time(seconds: float) -> str:
    if seconds < 60:
        return f"{seconds:.2f} sec"
    mins = int(seconds // 60)
    secs = seconds % 60
    return f"{mins} min {secs:.2f} sec"

def detect_query_type(question: str) -> str:
    q = question.lower().strip()
    if any(k in q for k in ["summary","summarize","overview","brief","outline","gist","tldr"]):
        return "FULL_SUMMARY"
    if any(k in q for k in ["list","all","every","what are","how many","enumerate","types of","examples of","mention"]):
        return "MULTIPART_QA"
    if any(k in q for k in ["why","how does","explain","what would","compare","difference","relationship","impact","effect"]):
        return "REASONING_QA"
    return "FACTUAL_QA"

def detect_doc_type(text: str) -> str:
    sample = text[:1000].lower()
    if any(w in sample for w in ["abstract","methodology","conclusion","research","university","lecture"]):
        return "academic"
    if any(w in sample for w in ["whereas","clause","agreement","party","hereby","legal","contract"]):
        return "legal"
    if any(w in sample for w in ["api","function","install","configure","technical","specification"]):
        return "technical"
    return "general"

# ============================================================
# NEW: LLM QUALITY METRICS
# ============================================================
def compute_answer_grounding(answer: str, context_chunks: list) -> float:
    """
    Answer Grounding = % of answer words found in context
    High score = answer is grounded in document
    Low score  = possible hallucination
    """
    if not answer or not context_chunks:
        return 0.0
    try:
        context_text = " ".join(context_chunks).lower()
        context_words = set(re.findall(r'\b[a-z]{4,}\b', context_text))
        answer_words  = set(re.findall(r'\b[a-z]{4,}\b', answer.lower()))
        if not answer_words:
            return 0.0
        overlap = answer_words & context_words
        return round(len(overlap) / len(answer_words) * 100, 1)
    except Exception:
        return 0.0

def compute_retrieval_score(question: str, docs: list) -> float:
    """
    Retrieval Score = avg cosine similarity of retrieved chunks to question
    Higher = more relevant chunks retrieved
    """
    try:
        q_embed = embedding_model.embed_query(question)
        sims = []
        for d in docs:
            d_embed = embedding_model.embed_query(d.page_content[:300])
            sim = np.dot(q_embed, d_embed) / (
                np.linalg.norm(q_embed) * np.linalg.norm(d_embed) + 1e-8)
            sims.append(sim)
        return round(float(np.mean(sims)) * 100, 2) if sims else 0.0
    except Exception:
        return 0.0

def compute_context_precision(question: str, docs: list, threshold: float = 0.3) -> float:
    """
    Context Precision = % of retrieved chunks that are relevant
    Relevant = similarity > threshold
    """
    try:
        q_embed = embedding_model.embed_query(question)
        relevant = 0
        for d in docs:
            d_embed = embedding_model.embed_query(d.page_content[:300])
            sim = np.dot(q_embed, d_embed) / (
                np.linalg.norm(q_embed) * np.linalg.norm(d_embed) + 1e-8)
            if sim > threshold:
                relevant += 1
        return round(relevant / len(docs) * 100, 1) if docs else 0.0
    except Exception:
        return 0.0

# ============================================================
# CORE: EXTRACT SINGLE PAGE
# ============================================================
def extract_page(args):
    page, page_num = args
    try:
        # Try fitz text extraction first (instant, no OCR)
        text = page.get_text().strip()
        if len(text) > 10:  # real text found — skip OCR entirely
            return page_num, text

        # Check if page has any renderable content at all
        # If page rect is tiny or page has no objects, skip OCR
        if page.rect.width < 10 or page.rect.height < 10:
            return page_num, ""

        # Only run OCR on pages that truly have no text
        # Use lower DPI first for speed — only go high if needed
        pix = page.get_pixmap(dpi=150)  # 150 dpi = 4x faster than 300
        img = Image.frombytes("RGB", [pix.width, pix.height], pix.samples)

        # Try only 0 degrees first (most pages are upright)
        try:
            t = pytesseract.image_to_string(img).strip()
            real_words = len([w for w in t.split() if len(w) > 2 and w.isalpha()])
            if real_words > 5:  # found readable text at 0 degrees
                return page_num, t
        except Exception:
            pass

        # Only try rotations if upright failed
        best_text = ""
        best_len = 0
        for angle in [90, 180, 270]:
            rotated = img.rotate(angle, expand=True)
            try:
                t = pytesseract.image_to_string(rotated).strip()
                real_words = len([w for w in t.split() if len(w) > 2 and w.isalpha()])
                if real_words > best_len:
                    best_len = real_words
                    best_text = t
            except Exception:
                continue

        return page_num, best_text.strip()
    except Exception:
        return page_num, ""

def extract_pdf_parallel(pdf_path: str):
    doc = fitz.open(pdf_path)
    page_count = len(doc)
    pages = [(doc[i], i) for i in range(page_count)]
    results = {}
    workers = min(MAX_WORKERS, page_count)
    with ThreadPoolExecutor(max_workers=workers) as ex:
        futures = {ex.submit(extract_page, p): p[1] for p in pages}
        for future in as_completed(futures):
            page_num, text = future.result()
            results[page_num] = text
    doc.close()
    full_text = " ".join(results[i] for i in sorted(results.keys()))
    full_text = re.sub(r'[^\x00-\x7F]+', ' ', full_text)
    full_text = re.sub(r'\s+', ' ', full_text).strip()
    return full_text, page_count

def semantic_chunk(text: str) -> list:
    splitter = RecursiveCharacterTextSplitter(
        chunk_size=CHUNK_SIZE, chunk_overlap=CHUNK_OVERLAP,
        separators=["\n\n", "\n", ". ", " ", ""])
    return splitter.split_text(text)

# ============================================================
# CORE: LLaMA CALLS
# ============================================================
def call_llama(prompt: str, num_ctx: int = 4096) -> str:
    try:
        response = ollama.chat(model=OLLAMA_MODEL,
            options={"num_ctx": num_ctx},
            messages=[{"role": "user", "content": prompt}])
        return response['message']['content'].strip()
    except Exception as e:
        return f"LLaMA error: {str(e)}"

def call_llama_streaming(prompt: str, request_id: str, num_ctx: int = 4096) -> str:
    """Streaming LLaMA — emits tokens live, TTFT drops to ~2 sec"""
    full_response = ""
    try:
        stream = ollama.chat(model=OLLAMA_MODEL,
            options={"num_ctx": num_ctx},
            messages=[{"role": "user", "content": prompt}],
            stream=True)
        for chunk in stream:
            token = chunk["message"]["content"]
            if token:
                full_response += token
                emit_event(request_id, "token", token)
        return full_response.strip()
    except Exception as e:
        return f"LLaMA error: {str(e)}"

# ============================================================
# CORE: TF-IDF EXTRACTIVE SUMMARY
# ============================================================
def extractive_summary(chunk: str, top_n: int = 3) -> str:
    sentences = re.split(r"(?<=[.!?])\s+", chunk.strip())
    sentences = [s.strip() for s in sentences if len(s.strip()) > 30]
    # Filter references
    sentences = [s for s in sentences
                 if not re.match(r'^\[\d+\]', s)
                 and not re.match(r'^\d+\.\s+[A-Z]', s)
                 and s.count('[') < 3]
    if not sentences:
        return chunk[:1000]
    if len(sentences) <= top_n:
        return " ".join(sentences)
    try:
        vectorizer = TfidfVectorizer(stop_words="english")
        tfidf_matrix = vectorizer.fit_transform(sentences)
        scores = np.array(tfidf_matrix.sum(axis=1)).flatten()
        top_indices = sorted(np.argsort(scores)[-top_n:].tolist())
        return " ".join(sentences[i] for i in top_indices)
    except Exception:
        return " ".join(sentences[:top_n])

# ============================================================
# CORE: RAPTOR HIERARCHICAL SUMMARY
# ============================================================
def raptor_summarize(chunks: list, doc_type: str):
    if not chunks:
        return "No content to summarize.", 0, 0

    map_start = time.time()
    with ThreadPoolExecutor(max_workers=MAX_WORKERS) as ex:
        futures = [ex.submit(extractive_summary, chunk, 3) for chunk in chunks]
        mini_summaries = [f.result() for f in futures if f.result().strip()]
    map_time = time.time() - map_start
    print(f"[RAPTOR] Map (TF-IDF): {len(mini_summaries)} chunks in {map_time:.1f}s")

    if not mini_summaries:
        return "Could not generate summary.", map_time, 0

    reduce_start = time.time()
    BATCH_CHARS = 15000
    batches = []
    current_batch = ""
    for summary in mini_summaries:
        if len(current_batch) + len(summary) > BATCH_CHARS and current_batch:
            batches.append(current_batch.strip())
            current_batch = summary + "\n\n"
        else:
            current_batch += summary + "\n\n"
    if current_batch.strip():
        batches.append(current_batch.strip())

    print(f"[RAPTOR] Reduce: {len(batches)} batches → LLaMA")
    partial_summaries = []
    for i, batch in enumerate(batches):
        prompt = (f"Extract the key points from this text section "
                  f"in clear bullet points. Be concise.\n\nText:\n{batch}\n\nKey points:")
        partial_summaries.append(call_llama(prompt))
        print(f"[RAPTOR] Batch {i+1}/{len(batches)} done")
        # Emit progress so browser knows we're alive
        if hasattr(raptor_summarize, '_request_id'):
            emit_event(raptor_summarize._request_id, "agent_action",
                       f"📝 Summary batch {i+1}/{len(batches)} complete...")

    if len(partial_summaries) == 1:
        final_summary = partial_summaries[0]
    else:
        merged = "\n\n---\n\n".join(partial_summaries)
        final_summary = call_llama(
            "Merge these section summaries into one comprehensive final summary. "
            "Remove repetition. Keep ALL key points. Use clear organized bullet points.\n\n"
            f"Section summaries:\n{merged[:12000]}\n\nFinal comprehensive summary:")

    reduce_time = time.time() - reduce_start
    total_calls = len(batches) + (1 if len(partial_summaries) > 1 else 0)
    print(f"[RAPTOR] Reduce done: {reduce_time:.1f}s | {total_calls} LLaMA calls | Total: {map_time+reduce_time:.1f}s")
    return final_summary, map_time, reduce_time

# ============================================================
# CORE: FAISS INDEX
# ============================================================
def build_faiss_index(chunks: list, pdf_hash: str):
    # CACHE DISABLED — fresh index every request for accurate testing
    # Re-enable after testing by adding load/save logic back
    print(f"[FAISS] Building fresh index ({len(chunks)} chunks)...")
    docs = [Document(page_content=c, metadata={"chunk_id": i})
            for i, c in enumerate(chunks)]
    return FAISS.from_documents(docs, embedding_model)

def roberta_qa(question: str, chunks: list):
    best_answer = ""
    best_score = 0.0
    for chunk in chunks:
        try:
            result = qa_pipeline(question=question, context=chunk[:2000])
            if result['score'] > best_score:
                best_score = result['score']
                best_answer = result['answer']
        except Exception:
            continue
    return best_answer, round(best_score, 4)

# ============================================================
# CORE: ReAct AGENT ENGINE
# ============================================================
def react_agent(question: str, faiss_index, query_type: str,
                request_id: str = "") -> tuple:
    MAX_STEPS = 3
    scratchpad = ""
    context_chunks = []
    model_used = "llama_react"
    llm_calls = 0

    k = 12 if query_type in ["MULTIPART_QA", "REASONING_QA"] else 6
    initial = faiss_index.similarity_search(question, k=k)
    context_chunks = [d.page_content for d in initial]
    retrieval_score = compute_retrieval_score(question, initial)
    context_precision = compute_context_precision(question, initial)

    print(f"[ReAct] Starting | {query_type} | retrieval={retrieval_score:.1f}%")
    emit_event(request_id, "agent_start",
               f"🤖 Agent starting | {query_type} | max {MAX_STEPS} steps")

    for step in range(MAX_STEPS):
        context = "\n\n---\n\n".join(context_chunks[:6])
        raw = call_llama(REACT_PROMPT.format(
            question=question, context=context[:3000],
            scratchpad=scratchpad if scratchpad else "None yet"))
        llm_calls += 1
        print(f"[ReAct] Step {step+1}: {raw[:120].strip()}")

        action = ""
        action_input = ""
        thought = raw[:100]
        lines = raw.split("\n")
        for i, line in enumerate(lines):
            line = line.strip()
            if line.startswith("Thought:"):
                thought = line.replace("Thought:", "").strip()
            elif line.startswith("Action:"):
                action_raw = line.replace("Action:", "").strip().lower()
                if "final" in action_raw or "answer" in action_raw:
                    action = "final_answer"
                elif "search" in action_raw or "more" in action_raw:
                    action = "search_more"
                else:
                    action = "final_answer"
            elif line.startswith("Input:"):
                action_input = line.replace("Input:", "").strip()
                for j in range(i+1, len(lines)):
                    next_line = lines[j].strip()
                    if next_line and not next_line.startswith(("Thought:", "Action:")):
                        action_input += " " + next_line
                    else:
                        break

        if not action:
            action = "final_answer"
            action_input = raw

        emit_event(request_id, "agent_thought", f"💭 Step {step+1}: {thought[:100]}")
        scratchpad += f"\nStep {step+1}: Thought={thought} | Action={action}\n"

        if "final_answer" in action:
            # Detect bad/unusable answers
            ans_clean = action_input.lower().strip()
            q_clean   = question.lower().strip()
            # Phrases that mean LLaMA gave up or echoed question
            cop_out_phrases = [
                "not enough context", "cannot answer", "no information",
                "not provided", "not mentioned", "unable to", "i cannot",
                "no context", "insufficient", "not available",
                "does not contain", "not found in"
            ]
            is_bad_input = (
                not action_input or
                len(action_input) < 50 or
                ans_clean == q_clean or
                ans_clean.startswith(q_clean[:20]) or
                q_clean[:30] in ans_clean or
                any(phrase in ans_clean for phrase in cop_out_phrases)
            )
            if is_bad_input:
                emit_event(request_id, "agent_action", "⚡ Using direct prompt...")
                context = "\n\n---\n\n".join(context_chunks[:6])
                emit_event(request_id, "stream_start", "✍️ Generating answer...")
                if query_type == "MULTIPART_QA":
                    answer = call_llama_streaming(MULTIPART_PROMPT.format(
                        context=context[:3000], question=question), request_id)
                elif query_type == "REASONING_QA":
                    answer = call_llama_streaming(REASONING_PROMPT.format(
                        context=context[:3000], question=question), request_id)
                else:
                    answer = call_llama_streaming(
                        f"Context:\n{context[:3000]}\n\nQuestion: {question}\n\nAnswer:",
                        request_id)
                llm_calls += 1
                model_used = "llama_react_direct"
                # Final safety check — if still echoing question, force retry
                if answer.lower().strip().startswith(question.lower()[:30]):
                    print(f"[ReAct] ⚠️ Answer still echoing question → force retry with stronger prompt")
                    answer = call_llama(
                        f"Using ONLY the document context below, answer this question completely.\n"
                        f"Do NOT repeat the question. Give a detailed answer.\n\n"
                        f"Context:\n{context[:3000]}\n\n"
                        f"Question: {question}\n\n"
                        f"Detailed Answer:"
                    )
                    llm_calls += 1
            else:
                answer = action_input
                model_used = "llama_react"

            grounding = compute_answer_grounding(answer, context_chunks)
            print(f"[ReAct] ✅ Answer at step {step+1} | grounding={grounding:.1f}%")
            emit_event(request_id, "agent_done", f"✅ Answer found at step {step+1}!")
            return answer, model_used, step+1, retrieval_score, context_precision, grounding, llm_calls

        elif "search_more" in action:
            query = action_input.strip('"\'') if action_input else question
            new_chunks = faiss_index.similarity_search(query, k=4)
            new_texts = [d.page_content for d in new_chunks]
            for t in new_texts:
                if t not in context_chunks:
                    context_chunks.append(t)
            print(f"[ReAct] 🔍 Searched: '{query}' → {len(new_texts)} chunks")
            emit_event(request_id, "agent_search",
                       f"🔍 Searching: '{query[:60]}' → {len(new_texts)} chunks found")
            scratchpad += f"  Found {len(new_texts)} additional chunks\n"
        else:
            if len(raw) > 20:
                grounding = compute_answer_grounding(raw, context_chunks)
                return raw, "llama_react_direct", step+1, retrieval_score, context_precision, grounding, llm_calls

    # Max steps
    emit_event(request_id, "agent_action", "⚡ Synthesizing final answer...")
    context = "\n\n---\n\n".join(context_chunks[:8])
    emit_event(request_id, "stream_start", "✍️ Generating final answer...")
    if query_type == "MULTIPART_QA":
        final = call_llama_streaming(MULTIPART_PROMPT.format(
            context=context[:3000], question=question), request_id)
    elif query_type == "REASONING_QA":
        final = call_llama_streaming(REASONING_PROMPT.format(
            context=context[:3000], question=question), request_id)
    else:
        final = call_llama_streaming(
            f"Context:\n{context[:3000]}\n\nQuestion: {question}\n\nAnswer:",
            request_id)
    llm_calls += 1
    grounding = compute_answer_grounding(final, context_chunks)
    return final, "llama_react_final", MAX_STEPS, retrieval_score, context_precision, grounding, llm_calls

# ============================================================
# LANGGRAPH NODES
# ============================================================
def node_extract(state: DocState) -> DocState:
    extract_start = time.time()
    text, page_count = extract_pdf_parallel(state["pdf_path"])
    extract_time = time.time() - extract_start
    state["extracted_text"] = text
    state["page_count"] = page_count
    state["char_count"] = len(text)
    state["metrics"]["extraction_time_sec"] = round(extract_time, 2)
    state["metrics"]["pages_processed"] = page_count
    state["metrics"]["characters_processed"] = len(text)
    state["metrics"]["words_processed"] = len(text.split())
    return state

def node_chunk(state: DocState) -> DocState:
    text = state["extracted_text"]
    state["doc_type"] = detect_doc_type(text)
    state["query_type"] = detect_query_type(state["question"])
    state["chunks"] = semantic_chunk(text)
    state["metrics"]["chunks_created"] = len(state["chunks"])
    state["metrics"]["doc_type"] = state["doc_type"]
    state["metrics"]["query_type"] = state["query_type"]
    return state

def node_summarize(state: DocState) -> DocState:
    summary_start = time.time()
    # Pass request_id to raptor for progress events
    raptor_summarize._request_id = state.get("request_id", "")
    summary, map_time, reduce_time = raptor_summarize(
        state["chunks"], state["doc_type"])
    summary_time = time.time() - summary_start
    state["answer"] = summary
    state["metrics"]["summary_time_sec"] = round(summary_time, 2)
    state["metrics"]["summary_length_words"] = len(summary.split())
    state["metrics"]["parallel_workers"] = min(MAX_WORKERS, len(state["chunks"]))
    state["metrics"]["map_time_sec"] = round(map_time, 2)
    state["metrics"]["reduce_time_sec"] = round(reduce_time, 2)
    state["metrics"]["llm_calls"] = 3  # batches + merge
    state["metrics"]["type"] = "summary"
    return state

def node_qa(state: DocState) -> DocState:
    qa_start = time.time()
    question = state["question"]
    query_type = state["query_type"]
    request_id = state.get("request_id", "")

    pdf_hash = get_pdf_hash(state["pdf_path"])
    faiss_index = build_faiss_index(state["chunks"], pdf_hash)

    print(f"[QA] Query type: {query_type}")

    if query_type == "FACTUAL_QA":
        print("[QA] Trying RoBERTa first...")
        k = 5
        retrieved = faiss_index.similarity_search(question, k=k)
        retrieved_texts = [d.page_content for d in retrieved]
        retrieval_score = compute_retrieval_score(question, retrieved)
        context_precision = compute_context_precision(question, retrieved)
        rob_answer, rob_score = roberta_qa(question, retrieved_texts)
        print(f"[QA] RoBERTa score: {rob_score}")

        if rob_score > 0.3 and rob_answer.strip():
            answer = rob_answer
            model_used = "roberta"
            grounding = compute_answer_grounding(answer, retrieved_texts)
            llm_calls = 0
            print(f"[QA] ✅ RoBERTa answered! grounding={grounding:.1f}%")
        else:
            print(f"[QA] ⚠️ RoBERTa low → ReAct agent...")
            answer, model_used, _, retrieval_score, context_precision, grounding, llm_calls = react_agent(
                question, faiss_index, query_type, request_id)
    else:
        print(f"[QA] Sending to ReAct agent ({query_type})...")
        answer, model_used, _, retrieval_score, context_precision, grounding, llm_calls = react_agent(
            question, faiss_index, query_type, request_id)

    qa_time = time.time() - qa_start
    print(f"[QA] Done in {qa_time:.1f}s | model={model_used} | grounding={grounding:.1f}%")

    if not answer.strip():
        answer = "Could not find a relevant answer in the PDF."

    state["answer"] = answer
    state["metrics"]["qa_time_sec"] = round(qa_time, 2)
    state["metrics"]["confidence_score"] = retrieval_score
    state["metrics"]["retrieval_score"] = retrieval_score
    state["metrics"]["context_precision"] = context_precision
    state["metrics"]["answer_grounding"] = grounding
    state["metrics"]["llm_calls"] = llm_calls
    state["metrics"]["model_used"] = model_used
    state["metrics"]["chunks_retrieved"] = k if query_type == "FACTUAL_QA" else 8
    state["metrics"]["type"] = "qa"
    return state

def node_validate(state: DocState) -> DocState:
    answer = state["answer"]
    retry = state.get("retry_count", 0)
    if len(answer.strip()) < 10 and retry < 2:
        state["retry_count"] = retry + 1
        state["answer"] = ""
        return state

    total_time = time.time() - state["start_time"]
    output_words = len(answer.split())
    output_tokens = output_words * 1.3
    tps = round(output_tokens / total_time, 2) if total_time > 0 else 0
    m = state["metrics"]

    # V1 METRICS
    m["response_time_sec"]    = round(total_time, 2)
    m["extraction_time_sec"]  = m.get("extraction_time_sec", 0)
    m["pages_processed"]      = state.get("page_count", 0)
    m["characters_processed"] = state.get("char_count", 0)
    m["words_processed"]      = len(state.get("extracted_text", "").split())
    if m.get("type") == "summary":
        m["summary_time_sec"]     = m.get("summary_time_sec", 0)
        m["summary_length_words"] = len(answer.split())
    if m.get("type") == "qa":
        m["qa_time_sec"]      = m.get("qa_time_sec", 0)
        m["confidence_score"] = m.get("confidence_score", 0)

    # V2 METRICS
    m["ttft_sec"]           = round(total_time, 2)
    m["e2e_latency_sec"]    = round(total_time, 2)
    m["tps"]                = tps
    m["doc_type"]           = state.get("doc_type", "general")
    m["query_type"]         = state.get("query_type", "")
    m["chunks_created"]     = m.get("chunks_created", 0)
    m["retry_count"]        = retry
    m["model_used"]         = m.get("model_used", "roberta")
    m["llm_calls"]          = m.get("llm_calls", 0)
    m["retrieval_score"]    = m.get("retrieval_score", 0)
    m["context_precision"]  = m.get("context_precision", 0)
    m["answer_grounding"]   = m.get("answer_grounding", 0)

    if m.get("type") == "summary":
        m["parallel_workers"] = m.get("parallel_workers", 0)
        m["map_time_sec"]     = m.get("map_time_sec", 0)
        m["reduce_time_sec"]  = m.get("reduce_time_sec", 0)
    if m.get("type") == "qa":
        m["chunks_retrieved"] = m.get("chunks_retrieved", 0)

    state["metrics"] = m
    return state

# ============================================================
# LANGGRAPH WORKFLOW
# ============================================================
def route_query(state: DocState) -> str:
    return "summarize" if state["query_type"] == "FULL_SUMMARY" else "qa"

def route_validate(state: DocState) -> str:
    if not state["answer"].strip() and state.get("retry_count", 0) < 2:
        return "retry"
    return "done"

def build_workflow():
    workflow = StateGraph(DocState)
    workflow.add_node("extract", node_extract)
    workflow.add_node("chunk", node_chunk)
    workflow.add_node("summarize", node_summarize)
    workflow.add_node("qa", node_qa)
    workflow.add_node("validate", node_validate)
    workflow.set_entry_point("extract")
    workflow.add_edge("extract", "chunk")
    workflow.add_conditional_edges("chunk", route_query,
        {"summarize": "summarize", "qa": "qa"})
    workflow.add_edge("summarize", "validate")
    workflow.add_edge("qa", "validate")
    workflow.add_conditional_edges("validate", route_validate,
        {"retry": "qa", "done": END})
    return workflow.compile()

print("Building LangGraph workflow...")
workflow = build_workflow()
print("Workflow ready!")

# ============================================================
# FLASK ROUTE
# ============================================================
@app.route("/process", methods=["POST"])
def process():
    data = request.json
    pdf_path   = data.get("pdf_path")
    question   = data.get("question")
    request_id = data.get("request_id", "")

    if not pdf_path or not question:
        return jsonify({"answer": "Missing PDF path or question."})
    if not os.path.exists(pdf_path):
        return jsonify({"answer": "File not found."})

    emit_event(request_id, "extract_start", "📄 Extracting PDF text...")

    initial_state: DocState = {
        "pdf_path": pdf_path, "question": question,
        "extracted_text": "", "chunks": [], "faiss_index": None,
        "answer": "", "metrics": {}, "doc_type": "general",
        "query_type": "", "retry_count": 0,
        "start_time": time.time(), "page_count": 0,
        "char_count": 0, "request_id": request_id
    }

    try:
        request_start = time.time()
        emit_event(request_id, "workflow_start", "⚙️ LangGraph workflow started...")
        result = workflow.invoke(initial_state)
        m = result["metrics"]
        total_e2e = round(time.time() - request_start, 2)
        m["e2e_latency_sec"] = total_e2e
        m["ttft_sec"] = m.get("ttft_sec", total_e2e)
        print(f"[LATENCY] E2E={total_e2e}s | TTFT={m['ttft_sec']}s | TPS={m.get('tps',0)}")
        if m.get("type") == "qa":
            print(f"[QUALITY] Grounding={m.get('answer_grounding',0)}% | Retrieval={m.get('retrieval_score',0)}% | Precision={m.get('context_precision',0)}%")
        emit_event(request_id, "done", "✅ Processing complete!")
        cleanup_queue(request_id)

        v1 = {
            "type": m.get("type", ""),
            "response_time_sec": round(m.get("response_time_sec", 0), 2),
            "extraction_time_sec": round(m.get("extraction_time_sec", 0), 2),
            "pages_processed": m.get("pages_processed", 0),
            "characters_processed": m.get("characters_processed", 0),
            "words_processed": m.get("words_processed", 0),
        }
        if m.get("type") == "summary":
            v1["summary_time_sec"]     = round(m.get("summary_time_sec", 0), 2)
            v1["summary_length_words"] = m.get("summary_length_words", 0)
        if m.get("type") == "qa":
            v1["qa_time_sec"]      = round(m.get("qa_time_sec", 0), 2)
            raw_conf = m.get("confidence_score", 0)
            v1["confidence_score"] = round(raw_conf/100, 4) if raw_conf > 1 else round(raw_conf, 4)

        v2 = {
            "ttft_sec":          round(m.get("ttft_sec", 0), 2),
            "e2e_latency_sec":   round(m.get("e2e_latency_sec", 0), 2),
            "tps":               m.get("tps", 0),
            "doc_type":          m.get("doc_type", "general"),
            "query_type":        m.get("query_type", ""),
            "model_used":        m.get("model_used", ""),
            "chunks_created":    m.get("chunks_created", 0),
            "retry_count":       m.get("retry_count", 0),
            "llm_calls":         m.get("llm_calls", 0),
            "retrieval_score":   m.get("retrieval_score", 0),
            "context_precision": m.get("context_precision", 0),
            "answer_grounding":  m.get("answer_grounding", 0),
        }
        if m.get("type") == "summary":
            v2["parallel_workers"] = m.get("parallel_workers", 0)
            v2["map_time_sec"]     = round(m.get("map_time_sec", 0), 2)
            v2["reduce_time_sec"]  = round(m.get("reduce_time_sec", 0), 2)
        if m.get("type") == "qa":
            v2["chunks_retrieved"] = m.get("chunks_retrieved", 0)

        return jsonify({
            "answer": result["answer"],
            "metrics": {**v1, **v2},
            "metrics_v1": v1,
            "metrics_v2": v2,
        })

    except Exception as e:
        return jsonify({"answer": f"Error: {str(e)}", "metrics": {}, "metrics_v1": {}, "metrics_v2": {}})

if __name__ == "__main__":
    print("Flask server running on http://127.0.0.1:5000")
    app.run(port=5000, threaded=False)  # prevent response mixing between requests






























